'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { LayersIcon, SearchIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxInputGroup,
  ComboboxItem,
  ComboboxList,
} from '@/registry/ndeko/ui/combobox';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import { CopyButton } from './_parts/copy-button';
import {
  ModalCloseButton,
  ModalDescription,
  ModalFooter,
  ModalHeader,
  ModalPreview,
  ModalTitle,
} from './_parts/modal-frame';
import { rowVariantsOf } from './_parts/motion';
import { CURRENT_USER, PEOPLE, type Person } from './_parts/people';
import { PersonAvatar } from './_parts/person-avatar';
import {
  ACCESS_LEVELS,
  RoleSelect,
  type AccessLevel,
} from './_parts/role-select';

type ProjectMember = { personId: string; access: AccessLevel };

type Candidate = { value: string; label: string; person: Person };

const PROJECT_NAME = 'Atlas redesign';

const PROJECT_LINK = 'https://lattice.example/projects/atlas-redesign';

const INITIAL_MEMBERS: ProjectMember[] = [
  { personId: 'lucas', access: 'manage' },
  { personId: 'priya', access: 'edit' },
  { personId: 'zola', access: 'view' },
];

function personOf(personId: string) {
  return PEOPLE.find((person) => person.id === personId);
}

function candidateOf(person: Person): Candidate {
  return { value: person.id, label: person.name, person };
}

function isCandidate(value: unknown): value is Candidate {
  const isObject = typeof value === 'object' && value !== null;
  return isObject && 'person' in value;
}

function MemberRow({
  member,
  onAccessChange,
  onRemove,
}: {
  member: ProjectMember;
  onAccessChange: (personId: string, access: AccessLevel) => void;
  onRemove: (personId: string) => void;
}) {
  const person = personOf(member.personId);
  if (!person) {
    return null;
  }

  function changeAccess(access: AccessLevel) {
    onAccessChange(member.personId, access);
  }

  function remove() {
    onRemove(member.personId);
  }

  return (
    <div className='flex min-h-13 items-center gap-3 py-2 pr-1.5 pl-3'>
      <PersonAvatar person={person} presence={person.presence} />
      <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <p className='truncate text-[13px] leading-tight font-medium'>
          {person.name}
        </p>
        <p className='text-muted-foreground truncate text-xs leading-tight'>
          {person.email}
        </p>
      </div>
      <RoleSelect
        label={`Access of ${person.name}`}
        value={member.access}
        options={ACCESS_LEVELS}
        onValueChange={changeAccess}
      />
      <Button
        variant='ghost'
        size='icon-sm'
        aria-label={`Remove ${person.name} from the project`}
        onClick={remove}
        className='text-muted-foreground'
      >
        <XIcon />
      </Button>
    </div>
  );
}

function OwnerRow() {
  return (
    <div className='flex min-h-13 items-center gap-3 py-2 pr-3 pl-3'>
      <PersonAvatar person={CURRENT_USER} presence={CURRENT_USER.presence} />
      <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <p className='flex items-center gap-1.5 text-[13px] leading-tight font-medium'>
          <span className='truncate'>{CURRENT_USER.name}</span>
          <Badge variant='secondary' className='text-muted-foreground'>
            You
          </Badge>
        </p>
        <p className='text-muted-foreground truncate text-xs leading-tight'>
          {CURRENT_USER.email}
        </p>
      </div>
      <span className='text-muted-foreground text-xs'>Owner</span>
    </div>
  );
}

function InviteToProject() {
  const [members, setMembers] = useState<ProjectMember[]>(INITIAL_MEMBERS);
  const [query, setQuery] = useState('');
  const [defaultAccess, setDefaultAccess] = useState<AccessLevel>('edit');
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowVariants = rowVariantsOf(shouldReduceMotion);
  const headingId = useId();
  const memberIds = members.map((member) => member.personId);
  const outsiders = PEOPLE.filter((person) => {
    const isOwner = person.id === CURRENT_USER.id;
    const isMember = memberIds.includes(person.id);
    return !isOwner && !isMember;
  });
  const candidates = outsiders.map(candidateOf);
  const memberCount = members.length + 1;
  const trimmedQuery = query.trim();

  function changeQuery(nextQuery: string) {
    setQuery(nextQuery);
  }

  function addCandidate(value: unknown) {
    if (!isCandidate(value)) {
      return;
    }
    const added: ProjectMember = {
      personId: value.person.id,
      access: defaultAccess,
    };
    setMembers((previous) => [added, ...previous]);
    setQuery('');
  }

  function changeAccess(personId: string, access: AccessLevel) {
    setMembers((previous) =>
      previous.map((member) => {
        if (member.personId !== personId) {
          return member;
        }
        return { ...member, access };
      })
    );
  }

  function removeMember(personId: string) {
    setMembers((previous) =>
      previous.filter((member) => member.personId !== personId)
    );
  }

  return (
    <>
      <div className='flex items-start gap-3 pr-8'>
        <span className='gem-plate flex size-9 shrink-0 items-center justify-center rounded-lg [--gem:var(--info)]'>
          <LayersIcon className='size-4' strokeWidth={2.25} />
        </span>
        <ModalHeader className='pr-0'>
          <ModalTitle>{`Invite to ${PROJECT_NAME}`}</ModalTitle>
          <ModalDescription>
            Teammates get the tasks, files and discussions of the project
          </ModalDescription>
        </ModalHeader>
      </div>
      <Combobox
        items={candidates}
        value={null}
        onValueChange={addCandidate}
        inputValue={query}
        onInputValueChange={changeQuery}
      >
        <ComboboxInputGroup className='min-h-9 flex-nowrap gap-1.5 py-1 pr-1 pl-2.5'>
          <SearchIcon className='text-muted-foreground size-4 shrink-0' />
          <ComboboxInput
            aria-label='Add teammates by name or e-mail'
            placeholder='Add teammates by name or e-mail'
            className='h-7'
          />
          <RoleSelect
            label='Access of the people you add'
            value={defaultAccess}
            options={ACCESS_LEVELS}
            onValueChange={setDefaultAccess}
          />
        </ComboboxInputGroup>
        <ComboboxContent className='p-1'>
          <ComboboxEmpty>
            {`Nobody else in Lattice matches “${trimmedQuery}”`}
          </ComboboxEmpty>
          <ComboboxList className='max-h-64 overflow-y-auto empty:hidden'>
            {(candidate: Candidate) => (
              <ComboboxItem
                key={candidate.value}
                value={candidate}
                className='h-auto py-1.5'
              >
                <PersonAvatar
                  person={candidate.person}
                  size='sm'
                  presence={candidate.person.presence}
                />
                <span className='flex min-w-0 flex-col'>
                  <span className='truncate text-[13px]'>
                    {candidate.person.name}
                  </span>
                  <span className='text-muted-foreground truncate text-xs'>
                    {candidate.person.email}
                  </span>
                </span>
              </ComboboxItem>
            )}
          </ComboboxList>
        </ComboboxContent>
      </Combobox>
      <section aria-labelledby={headingId} className='flex flex-col gap-2'>
        <div className='flex items-center gap-2'>
          <h3
            id={headingId}
            className='text-muted-foreground text-xs font-medium'
          >
            In this project
          </h3>
          <Kbd>
            <MotionNumber value={memberCount} />
          </Kbd>
        </div>
        <ul className='bg-card hairline-ring ring-border flex flex-col overflow-hidden rounded-xl py-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
          <li>
            <OwnerRow />
          </li>
          <AnimatePresence initial={false}>
            {members.map((member) => (
              <motion.li
                key={member.personId}
                variants={rowVariants}
                initial='hidden'
                animate='shown'
                exit='hidden'
              >
                <MemberRow
                  member={member}
                  onAccessChange={changeAccess}
                  onRemove={removeMember}
                />
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      </section>
      <ModalFooter className='sm:justify-between'>
        <CopyButton
          text={PROJECT_LINK}
          label='Copy project link'
          glyph='link'
          variant='ghost'
          announcement='Project link copied'
        />
        <ModalCloseButton>Done</ModalCloseButton>
      </ModalFooter>
    </>
  );
}

export default function Modal04() {
  return (
    <ModalPreview triggerLabel='Open the project invite dialog' size='lg'>
      <InviteToProject />
    </ModalPreview>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { CheckIcon, CopyIcon, LinkIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { Swap } from './swap';

const COPIED_RESET_MS = 1600;

/** Copies a text and says so for a moment. */
export function useCopy(text: string) {
  const [isCopied, setIsCopied] = useState(false);

  useEffect(() => {
    if (!isCopied) {
      return;
    }
    const timeout = window.setTimeout(() => {
      setIsCopied(false);
    }, COPIED_RESET_MS);
    return () => window.clearTimeout(timeout);
  }, [isCopied]);

  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setIsCopied(true);
    } catch {
      setIsCopied(false);
    }
  }

  return { isCopied, copy };
}

type CopyGlyph = 'copy' | 'link';

function glyphOf(isCopied: boolean, glyph: CopyGlyph) {
  if (isCopied) {
    return <CheckIcon className='text-success-foreground' />;
  }
  if (glyph === 'link') {
    return <LinkIcon />;
  }
  return <CopyIcon />;
}

function labelOf(isCopied: boolean, label: string, copiedLabel: string) {
  if (isCopied) {
    return copiedLabel;
  }
  return label;
}

type CopyButtonProps = Omit<ButtonProps, 'children' | 'onClick'> & {
  text: string;
  /** Visible label. Leave it out for an icon button, and give `aria-label` instead. */
  label?: string;
  copiedLabel?: string;
  /** Announced once the text is on the clipboard. */
  announcement: string;
  glyph?: CopyGlyph;
};

/** A copy action whose icon becomes a check and whose label becomes Copied, then returns. */
export function CopyButton({
  text,
  label,
  copiedLabel = 'Copied',
  announcement,
  glyph = 'copy',
  variant = 'outline',
  size = 'sm',
  ...props
}: CopyButtonProps) {
  const { isCopied, copy } = useCopy(text);
  const icon = glyphOf(isCopied, glyph);
  const iconKey = String(isCopied);
  const hasLabel = Boolean(label);
  const shownLabel = labelOf(isCopied, label ?? '', copiedLabel);

  return (
    <>
      <Button variant={variant} size={size} onClick={copy} {...props}>
        <Swap swapKey={iconKey}>{icon}</Swap>
        {hasLabel && (
          <AnimatedSize axis='width' as='span'>
            <Swap swapKey={shownLabel} kind='label'>
              {shownLabel}
            </Swap>
          </AnimatedSize>
        )}
      </Button>
      <span className='sr-only' role='status'>
        {isCopied && announcement}
      </span>
    </>
  );
}

'use client';

import { createContext, useContext } from 'react';

import { SquareArrowOutUpRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/registry/ndeko/ui/dialog';

/** Where a modal's content is drawn: open in the page as a preview, or inside the real dialog. */
export type ModalHost = 'preview' | 'dialog';

const ModalHostContext = createContext<ModalHost>('preview');

export function useModalHost() {
  return useContext(ModalHostContext);
}

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl';

const SIZE_CLASS: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-md',
  lg: 'max-w-lg',
  xl: 'max-w-[44rem]',
};

const TITLE = 'text-lg leading-tight font-semibold text-balance';

const DESCRIPTION = 'text-muted-foreground text-[13px]';

const BODY = 'flex flex-col gap-4';

type ModalTextProps = { className?: string; children: React.ReactNode };

export function ModalTitle({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogTitle className={className}>{children}</DialogTitle>;
  }
  return <h2 className={cn(TITLE, className)}>{children}</h2>;
}

export function ModalDescription({ className, children }: ModalTextProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return (
      <DialogDescription className={className}>{children}</DialogDescription>
    );
  }
  return <p className={cn(DESCRIPTION, className)}>{children}</p>;
}

/** Leaves room for the dialog's close button, so the preview and the dialog lay out the same. */
export function ModalHeader({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div className={cn('flex flex-col gap-1.5 pr-8', className)} {...props} />
  );
}

export function ModalFooter({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn(
        'flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end',
        className
      )}
      {...props}
    />
  );
}

/** Closes the dialog. In the preview it stays a plain button that runs its own action, if any. */
export function ModalCloseButton({ children, ...props }: ButtonProps) {
  const host = useModalHost();
  if (host === 'dialog') {
    return <DialogClose render={<Button {...props} />}>{children}</DialogClose>;
  }
  return <Button {...props}>{children}</Button>;
}

type ModalPreviewProps = {
  /** The content, drawn twice: open in the page, and inside the dialog the trigger opens. */
  children: React.ReactNode;
  triggerLabel: string;
  size?: ModalSize;
  className?: string;
};

/** Shows a modal open and whole on the page, with a small trigger that opens the same content in the real dialog. */
export function ModalPreview({
  children,
  triggerLabel,
  size = 'md',
  className,
}: ModalPreviewProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <div className='flex w-full flex-col items-center gap-4'>
      <ModalHostContext.Provider value='preview'>
        <div
          className={cn(
            'surface-raised w-full rounded-2xl p-6 text-left',
            sizeClass,
            className
          )}
        >
          <AnimatedSize contentClassName={BODY}>{children}</AnimatedSize>
        </div>
      </ModalHostContext.Provider>
      <Dialog>
        <DialogTrigger render={<Button variant='outline' size='sm' />}>
          <SquareArrowOutUpRightIcon />
          {triggerLabel}
        </DialogTrigger>
        <DialogContent className={cn(sizeClass, className)}>
          <ModalHostContext.Provider value='dialog'>
            {children}
          </ModalHostContext.Provider>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import type { Transition, Variants } from 'motion/react';

export const SWAP_TRANSITION: Transition = {
  duration: 0.15,
  ease: [0.2, 0, 0, 1],
};

const MORPH_SPRING: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const PRESENCE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const PRESENCE_OUT: Transition = { duration: 0.14, ease: [0.23, 1, 0.32, 1] };

const ICON_SWAP: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const LABEL_SWAP: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, filter: 'blur(2px)' },
};

const FADE_SWAP: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ROW_PRESENCE: Variants = {
  hidden: {
    height: 0,
    opacity: 0,
    overflow: 'hidden',
    transition: PRESENCE_OUT,
  },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: PRESENCE_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const ROW_FADE: Variants = {
  hidden: { opacity: 0, transition: PRESENCE_OUT },
  shown: { opacity: 1, transition: PRESENCE_IN },
};

const CHIP_PRESENCE: Variants = {
  hidden: { opacity: 0, scale: 0.9, transition: PRESENCE_OUT },
  shown: { opacity: 1, scale: 1, transition: PRESENCE_IN },
};

export type SwapKind = 'icon' | 'label';

export function swapVariantsOf(
  shouldReduceMotion: boolean | null,
  kind: SwapKind = 'icon'
) {
  if (shouldReduceMotion) {
    return FADE_SWAP;
  }
  if (kind === 'label') {
    return LABEL_SWAP;
  }
  return ICON_SWAP;
}

/** A row added to or removed from a list: its height opens or collapses, so the rows after it slide. */
export function rowVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return ROW_PRESENCE;
}

export function chipVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return ROW_FADE;
  }
  return CHIP_PRESENCE;
}

export function morphOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return MORPH_SPRING;
}

